import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';const out='docs/verification/three-agent-preparation-20261106',t=JSON.parse(fs.readFileSync(out+'/prepared-target.json','utf8')),require=createRequire(import.meta.url),{chromium}=require(path.join(process.env.USERPROFILE,'.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'));let browser;const checks=[],errors=[],writes=[];const check=(name,pass)=>{checks.push({name,pass:!!pass});if(!pass)throw Error(name);};try{browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});const page=await browser.newPage({viewport:{width:1440,height:900}});page.on('pageerror',e=>errors.push(e.message));await page.route('**/*',r=>{const q=r.request(),u=new URL(q.url());if(u.origin!=='http://127.0.0.1:3000')return r.abort();if(!['GET','HEAD'].includes(q.method())){if(q.method()!=='POST'||u.pathname!=='/api/console/studio/projects/'+t.projectId+'/roles')return r.abort();writes.push(u.pathname);}return r.continue();});const response=await page.goto('http://127.0.0.1:3000/team#project/'+t.projectId+'/chat/'+t.sessionId);await page.waitForFunction(id=>state.studioDetail?.id===id&&!state.busy,t.sessionId);check('Regular dashboard loads the actual prepared session',response.status()===200);check('No execution approval, worker attempt or writable access',await page.evaluate(()=>!state.studioDetail.state.runApproval&&!state.studioDetail.executions.length&&state.data.studio.projects.find(p=>p.id===state.studioProject).agentChangesAllowed===false));await page.locator('#chat-execution-tools>summary').click();await page.locator('.workspace-role-settings>summary').click();check('Correct three roles shown in labelled controls',await page.getByLabel('Builder agent',{exact:true}).inputValue()==='deepseek'&&await page.getByLabel('Tester agent',{exact:true}).inputValue()==='codex-personal'&&await page.getByLabel('Reviewer agent',{exact:true}).inputValue()==='claude-code');await page.getByLabel('Tester agent',{exact:true}).selectOption('deepseek');const pending=page.waitForResponse(r=>r.url().endsWith('/studio/projects/'+t.projectId+'/roles')&&r.request().method()==='POST');await page.getByRole('button',{name:'Save roles',exact:true}).click();const res=await pending,body=await res.json(),message=body.error?.message||body.error||body.message||'';check('Actual backend rejects Builder-as-Tester with the precise independence reason',res.status()===409&&/Tester must be independent/.test(String(message)));await page.reload();await page.waitForFunction(id=>state.studioDetail?.id===id&&!state.busy,t.sessionId);check('Rejected assignment leaves original roles intact after refresh',await page.evaluate(()=>state.studioDetail.state.roles.builder==='deepseek'&&state.studioDetail.state.roles.tester==='codex-personal'&&state.studioDetail.state.roles.reviewer==='claude-code'));check('Send remains disabled until owner authorization steps',await page.getByRole('button',{name:'Send',exact:true}).isDisabled());await page.screenshot({path:out+'/regular-dashboard-final.png',fullPage:true});check('No JavaScript errors or horizontal page overflow',errors.length===0&&await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));fs.writeFileSync(out+'/regular-dashboard-final.json',JSON.stringify({checks,passed:checks.length,errors,writeAttempts:writes,expectedRejection:409,modelRequests:0,scopeActivated:false},null,2));console.log(JSON.stringify({checks,passed:checks.length,errors,modelRequests:0},null,2));}catch(e){fs.writeFileSync(out+'/regular-dashboard-error.json',JSON.stringify({message:e.message,checks,errors},null,2));process.exitCode=1;}finally{await browser?.close();}
